using System;using System.IO;using System.Collections.Generic;using ScoreModern.RecoveredFragments;
class InputRhythmRecordsProof {
 static List<float[]> Records(byte[] b,int count){int n=0;var rows=new List<float[]>();while(n<count){var row=new float[15];Buffer.BlockCopy(b,n*60,row,0,60);rows.Add(row);n++;}return rows;}
 static int Main(string[] a){try{byte[] ds=File.ReadAllBytes(a[1]);byte[] common=File.ReadAllBytes(a[0]);var rows=Records(common,BitConverter.ToInt16(ds,0x8798));byte[] input=File.ReadAllBytes(a[2]),bounds=File.ReadAllBytes(a[3]);int n=BitConverter.ToInt16(ds,0x879c);float[] rhythms=new float[n];Buffer.BlockCopy(input,2,rhythms,0,n*4);float staff=BitConverter.ToSingle(ds,0x8780),scale=BitConverter.ToSingle(ds,0x8040+(int)staff*4)/25;int[] stems=new int[BitConverter.ToInt16(ds,0x8788)];for(int i=0;i<stems.Length;i++)stems[i]=BitConverter.ToInt16(common,0x2a30+i*2);var result=InputRhythmRecords.Apply(rows,rhythms,BitConverter.ToSingle(bounds,0),BitConverter.ToSingle(bounds,4),scale,BitConverter.ToInt16(ds,0x8790)<0,BitConverter.ToSingle(ds,0x3a70),stems);byte[] expected=File.ReadAllBytes(a[4]);int comparisons=0;for(int i=0;i<result.Count;i++)for(int p=0;p<(a.Length>5?int.Parse(a[5]):15);p++){int actual=BitConverter.ToInt32(BitConverter.GetBytes(result[i][p]),0),want=BitConverter.ToInt32(expected,i*60+p*4);if(actual!=want)throw new Exception("Record "+i+" P"+(p+1)+" "+actual.ToString("x8")+" != "+want.ToString("x8"));comparisons++;}Console.WriteLine("PASS "+comparisons+" original rhythm parameter words (bounded by the requested record fields).");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
